import{_ as e,o as l,c as i,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"ClickHouse / DuckDB / Snowflake 设计","description":"","frontmatter":{},"headers":[],"relativePath":"databases/olap/columnar.md","filePath":"databases/olap/columnar.md","lastUpdated":1788475713000}'),t={name:"databases/olap/columnar.md"};function n(o,a,r,c,d,p){return l(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="clickhouse-duckdb-snowflake-设计" tabindex="-1">ClickHouse / DuckDB / Snowflake 设计 <a class="header-anchor" href="#clickhouse-duckdb-snowflake-设计" aria-label="Permalink to &quot;ClickHouse / DuckDB / Snowflake 设计&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>三个新一代 OLAP 引擎代表了三种架构方向：MPP shared-nothing（ClickHouse）、单机嵌入式向量化（DuckDB）、存算分离云原生（Snowflake）。各自取舍反映了不同规模与 workload 下的工程权衡。本节带你看完三个引擎的 storage layout、metadata server / consensus decision sequence、compression format、query execution path、最近 5 年客户群对比。</p><hr><h2 id="一、clickhouse-yandex-2016" tabindex="-1">一、ClickHouse (Yandex 2016) <a class="header-anchor" href="#一、clickhouse-yandex-2016" aria-label="Permalink to &quot;一、ClickHouse (Yandex 2016)&quot;">​</a></h2><h3 id="_1-1-架构" tabindex="-1">1.1 架构 <a class="header-anchor" href="#_1-1-架构" aria-label="Permalink to &quot;1.1 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---+    +---+</span></span>
<span class="line"><span>| N | &lt;-&gt; | N |  (replica via ZooKeeper / Keeper)</span></span>
<span class="line"><span>+---+    +---+</span></span>
<span class="line"><span>Shard 1       Shard 2</span></span></code></pre></div><p>特点：</p><ul><li>shared-nothing：每个 shard 一个节点，replication via cluster.xml + ZooKeeper</li><li>mergeTree 引擎，每分钟一批 part 合并</li><li>vectorized batch processing (1024-8192 rows per batch)</li><li>跨 shard query 用 native protocol 解读</li></ul><h3 id="_1-2-mergetree" tabindex="-1">1.2 MergeTree <a class="header-anchor" href="#_1-2-mergetree" aria-label="Permalink to &quot;1.2 MergeTree&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Table storage = parts:</span></span>
<span class="line"><span>  part_001:</span></span>
<span class="line"><span>    - columns file (one per column)</span></span>
<span class="line"><span>    - primary.idx (sparse index every 8192 rows)</span></span>
<span class="line"><span>    - skip idx file (lightweight: min/max/null)</span></span>
<span class="line"><span>    - checksums</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  part_002 ...</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>INSERT INTO t VALUES (...)</span></span>
<span class="line"><span>  → 创建 new part on disk (default part_size ~ 150MB)</span></span>
<span class="line"><span>  → background merge: 多 part → 大 part (10GB+)</span></span></code></pre></div><p>skip index 算法：</p><ul><li><code>minmax</code>：极值索引</li><li><code>set</code>：value 集合</li><li><code>bloom_filter</code>：等值 filter</li><li><code>ngrambf_v1</code> (ngram bloom)：模糊匹配 LIKE</li></ul><h3 id="_1-3-replication" tabindex="-1">1.3 Replication <a class="header-anchor" href="#_1-3-replication" aria-label="Permalink to &quot;1.3 Replication&quot;">​</a></h3><ul><li><code>ReplicatedMergeTree</code> 引擎：每 part 增/删在 ZooKeeper 同步</li><li>multi-master：每 replica 独立读；写入 trigger 复制 log</li><li>不像 Raft/Paxos：ClickHouse 复制是 eventually + part 级别</li><li>新版 ClickHouse Keeper 替代 ZooKeeper（Raft 实现）</li></ul><h3 id="_1-4-性能与限制" tabindex="-1">1.4 性能与限制 <a class="header-anchor" href="#_1-4-性能与限制" aria-label="Permalink to &quot;1.4 性能与限制&quot;">​</a></h3><p>性能：</p><ul><li>vectorized aggregation，全 table scan 1 PB query &lt; 1 hr</li><li>拥抱 JSON / Map / Tuple 等 polymorphic 数据</li><li>没有 transaction overhead</li></ul><p>限制：</p><ul><li>没 OLTP：UPSERT 仅 batch mutation (background)</li><li>DDL 修改表难（ALTER 引擎 Class Hang），需 mutations</li><li>replication ZK 长期持有，高故障</li></ul><hr><h2 id="二、duckdb-cwi-2019" tabindex="-1">二、DuckDB (CWI 2019) <a class="header-anchor" href="#二、duckdb-cwi-2019" aria-label="Permalink to &quot;二、DuckDB (CWI 2019)&quot;">​</a></h2><h3 id="_2-1-架构" tabindex="-1">2.1 架构 <a class="header-anchor" href="#_2-1-架构" aria-label="Permalink to &quot;2.1 架构&quot;">​</a></h3><ul><li><strong>in-process OLAP</strong>：无 server, 一 (<code>libduckdb.so</code>) dll 直接链接</li><li>Python <code>import duckdb; duckdb.query(&quot;...&quot;)</code> 即 work</li><li>用 embedded StorageContext, 本地 file</li><li>vectorized engine (1024-row batches)</li></ul><h3 id="_2-2-设计哲学" tabindex="-1">2.2 设计哲学 <a class="header-anchor" href="#_2-2-设计哲学" aria-label="Permalink to &quot;2.2 设计哲学&quot;">​</a></h3><ul><li>OLAP 不需要 &quot;ACID&quot; 全弱化，仅 &quot;no consistency issues&quot;</li><li>不锁表，写 insert 加 incremental row (Morsel 固定大小 batch)</li><li>跨 platform: Windows / macOS / Linux / WSL / ARM</li><li>单机 (desktop scale) 通常 100 GBs OK，1+TB memory pressure 大</li></ul><h3 id="_2-3-性能" tabindex="-1">2.3 性能 <a class="header-anchor" href="#_2-3-性能" aria-label="Permalink to &quot;2.3 性能&quot;">​</a></h3><p>实测：</p><ul><li>TPC-H SF1 (1 GB) 10 秒 vs PG 5 分钟</li><li>TPC-H SF100 (100 GB) 5 分钟 vs Snowflake 2 分钟</li><li>SF1000 (1 TB) DuckDB benchmarks → 60 min (single-machine)</li></ul><h3 id="_2-4-优势与限制" tabindex="-1">2.4 优势与限制 <a class="header-anchor" href="#_2-4-优势与限制" aria-label="Permalink to &quot;2.4 优势与限制&quot;">​</a></h3><p>优势：</p><ul><li>部署极简：无服务部署</li><li>适合 streamlit / pandas-area workflow</li><li>高内存 (machine 32GB+) work 好</li></ul><p>限制：</p><ul><li>不真正 ETL：OLTP 后快流处理 dump file</li><li>没 distributed：单机 max CPU / RAM SIMD 只能 region-based</li><li>不支持多用户并发写</li></ul><hr><h2 id="三、snowflake-2014" tabindex="-1">三、Snowflake (2014) <a class="header-anchor" href="#三、snowflake-2014" aria-label="Permalink to &quot;三、Snowflake (2014)&quot;">​</a></h2><h3 id="_3-1-架构" tabindex="-1">3.1 架构 <a class="header-anchor" href="#_3-1-架构" aria-label="Permalink to &quot;3.1 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---+---+---+----+</span></span>
<span class="line"><span>| Cloud Services (metadata) |</span></span>
<span class="line"><span>|   - metadata server</span></span>
<span class="line"><span>|   - query optimizer</span></span>
<span class="line"><span>|   - authentication</span></span>
<span class="line"><span>|   - access control</span></span>
<span class="line"><span>+---+---+---+----+</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>+---+---+---+----+</span></span>
<span class="line"><span>| Compute (Virtual Warehouse) |</span></span>
<span class="line"><span>|   MPP cluster, 每节点 local SSD cache</span></span>
<span class="line"><span>+---+---+---+----+</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>+---+---+---+----+</span></span>
<span class="line"><span>| Storage (Object) |</span></span>
<span class="line"><span>|   S3 / GCS / Azure Blob</span></span>
<span class="line"><span>+---+---+---+----+</span></span></code></pre></div><ul><li>&quot;$/TB-scanned&quot; 计费：用户付 query 数据量</li><li>微 partitions (16MB block) + Stripe 索引</li><li>MPP 状态 serverless，autonomous 弹性</li></ul><h3 id="_3-2-微分区" tabindex="-1">3.2 微分区 <a class="header-anchor" href="#_3-2-微分区" aria-label="Permalink to &quot;3.2 微分区&quot;">​</a></h3><ul><li>16 MB 一个微 partition (slice)</li><li>每微 partition 存 column subset + min-max cutoff</li><li>SELECT 谓词在 metadata server 通过 column min/max → 跳分区</li><li>压缩 SNAPPY / LZ4 / 专用 (DELTA / STRING_DICTIONARY)</li></ul><h3 id="_3-3-result-cache" tabindex="-1">3.3 Result Cache <a class="header-anchor" href="#_3-3-result-cache" aria-label="Permalink to &quot;3.3 Result Cache&quot;">​</a></h3><p>Cloud Services 内 cache：query 同 hash 数秒内返回相同结果。</p><ul><li>90 second TTL</li><li>数据 vacuum 后 cache invalid</li></ul><h3 id="_3-4-性能与限制" tabindex="-1">3.4 性能与限制 <a class="header-anchor" href="#_3-4-性能与限制" aria-label="Permalink to &quot;3.4 性能与限制&quot;">​</a></h3><p>性能：</p><ul><li>local SSD cache layer: hot micro partitions cache 命中</li><li>tiered storage: 热数据 local SSD / S3 cold</li><li>vectorized query execution, 每 batch 8K-64K rows</li></ul><p>限制：</p><ul><li>没真正 MERGE ON primary key UPSERT</li><li>&quot;Time travel&quot; 90 天历史数据访问</li></ul><hr><h2 id="四、对比表" tabindex="-1">四、对比表 <a class="header-anchor" href="#四、对比表" aria-label="Permalink to &quot;四、对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>ClickHouse</th><th>DuckDB</th><th>Snowflake</th></tr></thead><tbody><tr><td>部署</td><td>server, MPP</td><td>in-process lib</td><td>SaaS cloud</td></tr><tr><td>Scale</td><td>1 PB</td><td>100 GB-1 TB</td><td>&gt;1 PB</td></tr><tr><td>隔离</td><td>multi tenant 慢 (server)</td><td>单 user 嵌入</td><td>virtual warehouse isolation</td></tr><tr><td>价格</td><td>自 deploy + OSS</td><td>free OSS</td><td>pay-per-TB scanned</td></tr><tr><td>延迟</td><td>ms-s 短 query</td><td>ms-秒</td><td>sec-min query</td></tr><tr><td>写 update</td><td>不擅长</td><td>一般</td><td>一般</td></tr><tr><td>Replication</td><td>ZK based</td><td>无 (本地文件)</td><td>S3 eventually + cache invalid</td></tr><tr><td>ACID</td><td>无</td><td>MVCC on local file</td><td>metadata transactional</td></tr><tr><td>Compression</td><td>LZ4+RLE+dict</td><td>col + RLE + dict</td><td>micropartition + multi compression</td></tr></tbody></table><hr><h2 id="五、其他-olap-engine" tabindex="-1">五、其他 OLAP Engine <a class="header-anchor" href="#五、其他-olap-engine" aria-label="Permalink to &quot;五、其他 OLAP Engine&quot;">​</a></h2><h3 id="_5-1-apache-druid" tabindex="-1">5.1 Apache Druid <a class="header-anchor" href="#_5-1-apache-druid" aria-label="Permalink to &quot;5.1 Apache Druid&quot;">​</a></h3><ul><li>kafka → historical node + deep storage</li><li>sub-second query 5 PB streaming-fed</li><li>适合 实时分析高可用 metrics</li></ul><h3 id="_5-2-apache-pinot" tabindex="-1">5.2 Apache Pinot <a class="header-anchor" href="#_5-2-apache-pinot" aria-label="Permalink to &quot;5.2 Apache Pinot&quot;">​</a></h3><ul><li>LinkedIn design 类 Druid</li><li>多 STM 模式 speed-up ingestion</li></ul><h3 id="_5-3-apache-kylin" tabindex="-1">5.3 Apache Kylin <a class="header-anchor" href="#_5-3-apache-kylin" aria-label="Permalink to &quot;5.3 Apache Kylin&quot;">​</a></h3><ul><li>Hadoop + HBase + OLAP cube precomputation</li><li>5 PB 但 阶段失效（low freshness）</li></ul><h3 id="_5-4-databricks-sql" tabindex="-1">5.4 Databricks SQL <a class="header-anchor" href="#_5-4-databricks-sql" aria-label="Permalink to &quot;5.4 Databricks SQL&quot;">​</a></h3><ul><li>类 Snowflake，但用户自管 Delta Lake</li><li>Spark vectorized engine</li></ul><h3 id="_5-5-firebolt" tabindex="-1">5.5 Firebolt <a class="header-anchor" href="#_5-5-firebolt" aria-label="Permalink to &quot;5.5 Firebolt&quot;">​</a></h3><ul><li>列存 + skip + f0 vectorized + indexing</li><li>类 Snowflake，新型 data ingest</li></ul><h3 id="_5-6-singlestore-memsql" tabindex="-1">5.6 SingleStore (MemSQL) <a class="header-anchor" href="#_5-6-singlestore-memsql" aria-label="Permalink to &quot;5.6 SingleStore (MemSQL)&quot;">​</a></h3><ul><li>HTAP 一体</li><li>列 + row combo</li><li>OLTP + analysis 同表</li></ul><hr><h2 id="六、产线案例" tabindex="-1">六、产线案例 <a class="header-anchor" href="#六、产线案例" aria-label="Permalink to &quot;六、产线案例&quot;">​</a></h2><h3 id="_6-1-clickhouse-写入瓶颈" tabindex="-1">6.1 ClickHouse 写入瓶颈 <a class="header-anchor" href="#_6-1-clickhouse-写入瓶颈" aria-label="Permalink to &quot;6.1 ClickHouse 写入瓶颈&quot;">​</a></h3><p>业务 100k INSERT/sec 单机磁盘 IO 占满。ClickHouse merge 跑死 → 5+ days backlog。</p><p><strong>修复</strong>：bulk insert batch 1M rows / <code>max_insert_block_size=1M</code>；多 shard 分写；turbo 编码 mode 极致压缩。</p><h3 id="_6-2-snowflake-small-query-高-cost" tabindex="-1">6.2 Snowflake small query 高 cost <a class="header-anchor" href="#_6-2-snowflake-small-query-高-cost" aria-label="Permalink to &quot;6.2 Snowflake small query 高 cost&quot;">​</a></h3><p>业务 dashboard 每 30 秒每 user query 小 → warehouse cost $30/hour。</p><p><strong>修复</strong>：启 result cache hit + auto-suspend 60s → $10/hour。</p><h3 id="_6-3-duckdb-embedded-oom-notebook" tabindex="-1">6.3 DuckDB embedded OOM (notebook) <a class="header-anchor" href="#_6-3-duckdb-embedded-oom-notebook" aria-label="Permalink to &quot;6.3 DuckDB embedded OOM (notebook)&quot;">​</a></h3><p>pandas <code>read_csv</code> 64 GB → DuckDB driver alloc all 数据 → memory &gt; RAM 几次 kill。</p><p><strong>修复</strong>：<code>PRAGMA memory_limit=&#39;2GB&#39;;</code> <code>SET threads=1;</code> + swap file。</p><h3 id="_6-4-clickhouse-replication-zk-故障" tabindex="-1">6.4 ClickHouse replication ZK 故障 <a class="header-anchor" href="#_6-4-clickhouse-replication-zk-故障" aria-label="Permalink to &quot;6.4 ClickHouse replication ZK 故障&quot;">​</a></h3><p>ZK → 部 partition lag → ClickHouse spinning.</p><p><strong>修复</strong>：升 Raft ClickHouse Keeper 替代 ZooKeeper。</p><h3 id="_6-5-snowflake-mark-forced-upsert-slow" tabindex="-1">6.5 Snowflake mark forced UPSERT slow <a class="header-anchor" href="#_6-5-snowflake-mark-forced-upsert-slow" aria-label="Permalink to &quot;6.5 Snowflake mark forced UPSERT slow&quot;">​</a></h3><p>SaaS UPSERT primary key 模式 metadata mark 但 render slow。</p><p><strong>修复</strong>：业务夜里全压 merge batch (insert + part override)。</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>ClickHouse 没 OLTP</strong>：UPSERT 走 mutations 后台 async</li><li><strong>Snowflake cost = query byte scanned</strong>：主成本驱动</li><li><strong>DuckDB</strong>：不可服务 model，每 user 嵌自</li><li><strong>ClickHouse mergeTree replication</strong>：古老 ZK 不能多 ZK cluster，升 ClickHouse Keeper (Raft)</li><li><strong>DuckDB <code>PRAGMA threads</code></strong> 设高 可 OOM</li><li><strong>ClickHouse Hybrid Log-Structured Merge Trees</strong>：老 MergeTree → 改 ReplicatedMergeTree</li><li><strong>Snowflake warehouse 大 T-shirt size</strong>：scaling 是 fixed（不 size 算每 warehouse 工资源）</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>ClickHouse: shared-nothing MPP + mergeTree + Vectorized 是 PB scale 自部署 OLAP</li><li>DuckDB: in-process + 8192-row vectorized + 单机性能比 PG 10-100×</li><li>Snowflake: micro-partitions + multi-tier (S3 + local SSD) + 云原生 + pay-per-byte</li><li>三选: 部署自控选 CH, embedded analytics 选 DuckDB, managed cloud 选 Snowflake</li><li>性能取决于：列压缩、batch size、SIMD 命中、缓存 localily</li><li>物化视图 + Rollup 是必要的，不是 optional</li></ol><h2 id="下一节-→" tabindex="-1">下一节 → <a class="header-anchor" href="#下一节-→" aria-label="Permalink to &quot;下一节 →&quot;">​</a></h2><p><a href="./materialized">预聚合、物化视图、Cubes</a> — Cube / Materialized View / Star Schema / Druid rollup</p>`,91)])])}const k=e(t,[["render",n]]);export{h as __pageData,k as default};
